namespace ArticleManagement.Model { public class PagingResult<T> { public T Items {get;set;} public int TotalCount {get;set;} } public class PagedList<T>:List<T> { public int TotalCount {get;private set;} public PagedList(List<T> items,int count){TotalCount=count;AddRange(items);} public static PagedList<T> ToPagedList(IQueryable<T> source,int pageNumber,int pageSize){var count=source.Count();var items=source.Skip((pageNumber-1)*pageSize).Take(pageSize).ToList();return new PagedList<T>(items,count);} } }